//! Qalaa Guardian: a small native mascot that floats above other windows,
//! reacts to what the background service reports, and opens a compact card of
//! quick actions. Off unless the person starts it.
//!
//! Everything that decides behaviour is pure and tested headless: the mood
//! state machine (`mood`), geometry and click-through (`geometry`, `hit`), the
//! per-OS overlay plan (`platform`), and the event mapping and layout here.

/// Code generated by the Slint compiler from `ui/pet.slint`.
#[allow(clippy::all, clippy::pedantic, clippy::unwrap_used)]
mod generated {
    slint::include_modules!();
}
pub use generated::*;

pub mod geometry;
pub mod hit;
pub mod mood;
pub mod platform;

use geometry::{place_popover, Rect};
use mood::{Input, Mood};
use qalaa_ipc::Event;

pub const SPRITE: f32 = 96.0;
pub const POPOVER: (f32, f32) = (280.0, 300.0);
pub const SKINS: [&str; 3] = ["mini-sentinel", "cyber-owl", "shield-fox"];

/// What a service event means for the pet; `None` for events it ignores.
pub fn input_for(event: &Event) -> Option<Input> {
    let count = |key: &str| event.payload.get(key).and_then(serde_json::Value::as_u64).unwrap_or(0);
    match event.name.as_str() {
        "scan.started" => Some(Input::ScanStarted),
        "scan.finished" => Some(Input::ScanFinished {
            threats: u32::try_from(count("malicious") + count("suspicious")).unwrap_or(u32::MAX),
        }),
        "threat.blocked" => Some(Input::ThreatBlocked),
        "alert" => Some(Input::Alert),
        _ => None,
    }
}

pub fn skin_from(arg: Option<&str>) -> &'static str {
    arg.and_then(|a| SKINS.iter().find(|s| **s == a).copied()).unwrap_or(SKINS[0])
}

/// Where everything goes. `window` is in screen coordinates; `sprite` and
/// `popover` are inside the window.
#[derive(Debug, Clone, PartialEq)]
pub struct Layout {
    pub window: Rect,
    pub sprite: Rect,
    pub popover: Option<Rect>,
}

/// The window is exactly the sprite, or the sprite plus the popover, so
/// everything outside them belongs to other windows.
pub fn layout(sprite_on_screen: (f32, f32), popover_open: bool, work_area: &Rect) -> Layout {
    let sprite = Rect::new(sprite_on_screen.0, sprite_on_screen.1, SPRITE, SPRITE);
    let popover = popover_open.then(|| place_popover(&sprite, POPOVER, work_area));
    let window = popover.map_or(sprite, |p| sprite.union(&p));
    let local = |r: &Rect| Rect::new(r.x - window.x, r.y - window.y, r.w, r.h);
    Layout {
        window,
        sprite: local(&sprite),
        popover: popover.as_ref().map(local),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lang {
    En,
    Ar,
}

impl Lang {
    pub fn detect(arg: Option<&str>) -> Self {
        let pick = arg
            .map(str::to_owned)
            .or_else(|| std::env::var("QALAA_LANG").ok())
            .or_else(|| std::env::var("LANG").ok())
            .unwrap_or_default();
        if pick.to_ascii_lowercase().starts_with("ar") {
            Lang::Ar
        } else {
            Lang::En
        }
    }
}

pub fn mood_text(mood: Mood, lang: Lang) -> &'static str {
    match (lang, mood) {
        (Lang::En, Mood::Idle) => "Keeping watch",
        (Lang::En, Mood::Patrol) => "On patrol",
        (Lang::En, Mood::Sleep) => "Resting, still protecting",
        (Lang::En, Mood::Scan) => "Scanning",
        (Lang::En, Mood::Defend) => "Blocked a threat",
        (Lang::En, Mood::Alert) => "Needs your attention",
        (Lang::En, Mood::Happy) => "Scan finished: nothing found",
        (Lang::Ar, Mood::Idle) => "في حالة مراقبة",
        (Lang::Ar, Mood::Patrol) => "في جولة حراسة",
        (Lang::Ar, Mood::Sleep) => "يستريح ولا يزال يحمي",
        (Lang::Ar, Mood::Scan) => "يفحص",
        (Lang::Ar, Mood::Defend) => "صدّ تهديدًا",
        (Lang::Ar, Mood::Alert) => "يحتاج إلى انتباهك",
        (Lang::Ar, Mood::Happy) => "انتهى الفحص: لم يُعثر على شيء",
    }
}

pub fn text(key: &str, lang: Lang) -> &'static str {
    match (lang, key) {
        (Lang::En, "sprite") => "Qalaa Guardian: open quick actions",
        (Lang::En, "scan.quick") => "Run a quick scan",
        (Lang::En, "signatures.update") => "Update malware fingerprints",
        (Lang::En, "open") => "Open Qalaa",
        (Lang::En, "snooze") => "Hide for 2 hours",
        (Lang::En, "offline") => "The Qalaa background service isn't running.",
        (Lang::En, "connected") => "Connected to Qalaa on this computer.",
        (Lang::Ar, "sprite") => "حارس قلعة: افتح الإجراءات السريعة",
        (Lang::Ar, "scan.quick") => "شغّل فحصًا سريعًا",
        (Lang::Ar, "signatures.update") => "حدّث بصمات البرمجيات الخبيثة",
        (Lang::Ar, "open") => "افتح قلعة",
        (Lang::Ar, "snooze") => "أخفِ لمدة ساعتين",
        (Lang::Ar, "offline") => "خدمة قلعة الخلفية لا تعمل.",
        (Lang::Ar, "connected") => "متصل بقلعة على هذا الحاسوب.",
        _ => "",
    }
}

/// The popover's buttons. Service actions are disabled while offline.
pub fn actions(lang: Lang, connected: bool) -> Vec<Action> {
    ["scan.quick", "signatures.update", "open", "snooze"]
        .iter()
        .map(|id| Action {
            id: (*id).into(),
            label: text(id, lang).into(),
            enabled: connected || matches!(*id, "open" | "snooze"),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn event(name: &str, payload: serde_json::Value) -> Event {
        Event {
            name: name.into(),
            payload,
        }
    }

    #[test]
    fn maps_service_events() {
        assert_eq!(input_for(&event("scan.started", json!({}))), Some(Input::ScanStarted));
        assert_eq!(
            input_for(&event("scan.finished", json!({"malicious": 1, "suspicious": 2}))),
            Some(Input::ScanFinished { threats: 3 })
        );
        assert_eq!(
            input_for(&event("scan.finished", json!({}))),
            Some(Input::ScanFinished { threats: 0 })
        );
        assert_eq!(input_for(&event("threat.blocked", json!({}))), Some(Input::ThreatBlocked));
        assert_eq!(input_for(&event("home.changed", json!({}))), None);
    }

    #[test]
    fn window_is_just_the_sprite_until_the_popover_opens() {
        let screen = Rect::new(0.0, 0.0, 1920.0, 1032.0);
        let closed = layout((1800.0, 920.0), false, &screen);
        assert_eq!(closed.window, Rect::new(1800.0, 920.0, SPRITE, SPRITE));
        assert_eq!(closed.sprite, Rect::new(0.0, 0.0, SPRITE, SPRITE));
        let open = layout((1800.0, 920.0), true, &screen);
        let pop = open.popover.expect("popover");
        // Above the sprite, inside the screen, and the window covers both.
        assert!(pop.y + pop.h <= open.sprite.y);
        assert!(open.window.x + pop.x + pop.w <= screen.w);
        assert!(open.window.w >= POPOVER.0 && open.window.h >= SPRITE + POPOVER.1);
    }

    #[test]
    fn every_text_in_both_languages() {
        for key in [
            "sprite",
            "scan.quick",
            "signatures.update",
            "open",
            "snooze",
            "offline",
            "connected",
        ] {
            assert!(!text(key, Lang::En).is_empty() && !text(key, Lang::Ar).is_empty(), "{key}");
        }
        assert_eq!(skin_from(Some("cyber-owl")), "cyber-owl");
        assert_eq!(skin_from(Some("dragon")), "mini-sentinel");
        let offline = actions(Lang::En, false);
        assert!(offline.iter().any(|a| a.id == "scan.quick" && !a.enabled));
        assert!(offline.iter().any(|a| a.id == "snooze" && a.enabled));
    }
}
